const WatchList = () => {
  const { watchlist: userWatchlist, refreshWatchlist } =
    useContext(GeneralContext);
  const [displayList, setDisplayList] = useState([]);
  const [chartData, setChartData] = useState(null);

  useEffect(() => {
    const fetchPrices = async () => {
      const updatedList = await Promise.all(
        userWatchlist.map(async (item) => {
          try {
            const res = await flask.get(`/price/${item.symbol}`);
            const price = res.data.price;
            const prev = item.prevPrice || price;
            const isDown = price < prev;
            const percent = prev
              ? `${(((price - prev) / prev) * 100).toFixed(2)}%`
              : "0.00%";
            return { ...item, price, percent, isDown };
          } catch {
            return { ...item, price: 0, percent: "0.00%", isDown: false };
          }
        })
      );

      setDisplayList(updatedList);
      setChartData({
        labels: updatedList.map((s) => s.symbol),
        datasets: [
          {
            label: "Price",
            data: updatedList.map((s) => s.price),
            backgroundColor: [
              "rgba(255, 99, 132, 0.5)",
              "rgba(54, 162, 235, 0.5)",
              "rgba(255, 206, 86, 0.5)",
              "rgba(75, 192, 192, 0.5)",
              "rgba(153, 102, 255, 0.5)",
              "rgba(255, 159, 64, 0.5)",
            ],
            borderColor: [
              "rgba(255, 99, 132, 1)",
              "rgba(54, 162, 235, 1)",
              "rgba(255, 206, 86, 1)",
              "rgba(75, 192, 192, 1)",
              "rgba(153, 102, 255, 1)",
              "rgba(255, 159, 64, 1)",
            ],
            borderWidth: 1,
          },
        ],
      });
    };

    if (userWatchlist.length > 0) fetchPrices();
  }, [userWatchlist]);

  return (
    <div className="watchlist-container">
      <div className="search-container">
        <Search />
        <span className="counts"> {displayList.length} / 50</span>
      </div>

      <ul className="list">
        {displayList.map((stock, index) => (
          <WatchListItem stock={stock} key={index} />
        ))}
      </ul>

      {chartData && <DoughnutChart data={chartData} />}
    </div>
  );
};
